def price_floor(t):
    old = '!Number.isFinite(Number(price)) || Number(price) > 9999999999.99)'
    new = '!Number.isFinite(Number(price)) || Number(price) < 0 || Number(price) > 9999999999.99)'
    assert old in t
    return t.replace(old, new, 1)
