fe.append_section(S, '02', '## Rejecting versus clamping a page size', """`const pageSize = whole(req.query.pageSize,1,1000000) ? Math.min(Number(req.query.pageSize),50) : 5;` does two different things in one line. A value that is not a whole number in 1..1000000 (`0`, `2.5`, `abc`) is *replaced* by the default 5: that is rejection with a fallback. A valid value above 50 is *clamped* to 50. Both are defensible, but a reader cannot tell which happened from the response unless `pageSize` is echoed back, which it is. Predict, then check with the new test: `?pageSize=500` -> 50, `?pageSize=0` -> 5, `?pageSize=2.5` -> 5. If you would rather answer 400 for a bad page size, that is exercise material; either way, say it in the API docs.""")
def patch_test(t):
    add = '''
test("page size is clamped when valid and defaulted when malformed", async () => {
  assert.equal((await call("/api/products?pageSize=500")).data.pageSize, 50);
  assert.equal((await call("/api/products?pageSize=0")).data.pageSize, 5);
  assert.equal((await call("/api/products?pageSize=2.5")).data.pageSize, 5);
  assert.equal((await call("/api/products?pageSize=7")).data.pageSize, 7);
});
'''
    return t.rstrip('\n') + '\n' + add
